import{_ as E,H as i,f as e,i as l}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"期中测试-来检验一下你的学习成果吧！","description":"","frontmatter":{},"headers":[],"relativePath":"中间件核心技术与实战/期中测试-来检验一下你的学习成果吧！.md","filePath":"中间件核心技术与实战/期中测试-来检验一下你的学习成果吧！.md","lastUpdated":1795537466000}'),a={name:"中间件核心技术与实战/期中测试-来检验一下你的学习成果吧！.md"};function p(_,t,s,o,A,B){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="期中测试-来检验一下你的学习成果吧" tabindex="-1">期中测试-来检验一下你的学习成果吧！ <a class="header-anchor" href="#期中测试-来检验一下你的学习成果吧" aria-label="Permalink to &quot;期中测试-来检验一下你的学习成果吧！&quot;">​</a></h1><p>你好，我是丁威。</p><p>不知不觉，我们的专栏已经进行到一半了。我们这个专栏的前半部分理论知识比较多，学起来比较枯燥，能坚持到这里，我首先要为你打 Call。这也说明你是真正的热爱技术，真心希望通过学习中间件技术突破瓶颈，在职场上过关斩将。俗话说，温故而知新，在开始后面的课程之前，我想通过提问的方式再跟你一起回顾一下前面的知识点。</p><p>请你试着回答下面这些问题，检验一下自己的学习成果。下节课，我会一一给出答案。预祝你取得好成绩！</p><ol><li><p>MyCat 数据库中间件与 ShardingJDBC 在架构思想上有什么差异？</p></li><li><p>在订单中心有创建订单、查询订单两个微服务。其中，查询订单必须同时支持“按商家”和“按用户”两个维度。为了应对双十一这种大促场景，在数据存储和数据读写方面你会如何进行</p></li></ol><ul><li>架构设计？</li></ul><ol start="3"><li>红黑树的左右旋转、染色其实是不需要死记硬背的。下面这棵二叉树，你会怎样操作让它符合红黑树的定义呢？</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595-%25E6%259D%25A5%25E6%25A3%2580%25E9%25AA%258C%25E4%25B8%2580%25E4%25B8%258B%25E4%25BD%25A0%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E6%2588%2590%25E6%259E%259C%25E5%2590%25A7%25EF%25BC%2581/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595-%25E6%259D%25A5%25E6%25A3%2580%25E9%25AA%258C%25E4%25B8%2580%25E4%25B8%258B%25E4%25BD%25A0%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E6%2588%2590%25E6%259E%259C%25E5%2590%25A7%25EF%25BC%2581/1.png" alt=""></a></p><ol start="4"><li><p>JUC 定时调度线程池底层的实现原理是什么？如果要管理上万个定时任务，需要怎么处理呢？</p></li><li><p>如何复用线程？如何优雅地停止一个线程？</p></li><li><p>多线程编程中，线程与线程之间有两种主要的关系：互斥与协作。你能结合自己的实际工作场景分别举例说明吗？</p></li><li><p>锁的底层数据结构是什么？</p></li><li><p>为什么 Object.wait 方法会释放占用的锁？如果锁没有被释放，会产生什么影响？</p></li><li><p>什么是 NIO？为什么 NIO 能轻松支持上万个连接同时在线？</p></li><li><p>我们在使用 NIO 构建的服务端时，如果服务端处理压力较大，可以在应用层采用快速失败拒绝连接。但是除此之外，在网络层，你还有什么办法限制服务端的流量呢？</p></li><li><p>通过 NIO 通道向网络中写数据之前，需要注册写事件吗？那什么时候需要注册写事件呢？</p></li><li><p>一个网络请求在发送端、接受端通常需要经历哪些步骤，Netty 又是采用什么线程模型使这些步骤合理高效运作的？</p></li></ol><p>期待你在留言区留下自己的思考和答案，我们下节课见！</p>',10)])])}const c=E(a,[["render",p]]);export{r as __pageData,c as default};
